    builder.entity(this.newErrorResponse(
        this.newMeta(httpMethod, BAD_REQUEST, timers),
        this.newLinks(uriInfo), errorMessage));
    builder.type(APPLICATION_JSON);
    return new BadRequestException(builder.build());
  }

