  /**
   * Completes the operation using the specified parameters to determine what
   * sort of request was made.
   *
   * @param eventBuilder The event builder if an SSE request.
   * @param sseEventSink The event sink if an SSE request.
   * @param eventId The event ID if an SSE request.
   * @param webSocketSession The web socket session if a web socket request.
   * @param response The response object to be sent.
   * @param <T> The type of the response object.
   *
   * @return The specified response object.
   */
  default <T extends SzBasicResponse> T completeOperation(
      OutboundSseEvent.Builder  eventBuilder,
      SseEventSink              sseEventSink,
      int                       eventId,
      Session                   webSocketSession,
      T                         response)
  {
    if (eventBuilder != null || webSocketSession != null) {
      // check if sending an SSE event
      if (eventBuilder != null) {
        OutboundSseEvent event
            = eventBuilder.name(COMPLETED_EVENT)
            .id(String.valueOf(eventId++))
            .mediaType(APPLICATION_JSON_TYPE)
            .data(response)
            .reconnectDelay(RECONNECT_DELAY)
            .build();
        sseEventSink.send(event);
        sseEventSink.close();
      }

      // check if sending a message on the web socket session
      if (webSocketSession != null) {
        try {
          webSocketSession.getBasicRemote().sendObject(response);
          webSocketSession.close();

        } catch (Exception e) {
          e.printStackTrace();
        }
      }

      // return null here if we sent the response
      return null;
    }

    // return the response
    return response;
  }

  /**
   * Aborts the operation using the specified parameters to determine what
   * sort of request was made.
   *
   * @param failure The failure that triggered the abort.
   * @param response The response object to send.
   * @param uriInfo The {@link UriInfo} for the request.
   * @param timers The {@link Timers} associated with the operation.
   * @param eventId The event ID if an SSE request.
   * @param eventBuilder The event builder if an SSE request.
   * @param sseEventSink The event sink if an SSE request.
   * @param webSocketSession The web socket session if a web sockets request.
   * @param <T> The type of the response object.
   * @return The specified response object.
   * @throws WebApplicationException If a web application failure occurs.
   */
  default <T extends SzBasicResponse> T abortOperation(
      Exception                 failure,
      T                         response,
      UriInfo                   uriInfo,
      Timers                    timers,
      int                       eventId,
      OutboundSseEvent.Builder  eventBuilder,
      SseEventSink              sseEventSink,
      Session                   webSocketSession)
      throws WebApplicationException
  {
    if (!isLastLoggedException(failure)) {
      failure.printStackTrace();
    }
    setLastLoggedException(failure);

    // determine if we need to construct an error response
    SzErrorResponse errorResponse = null;
    if (eventBuilder != null || webSocketSession != null) {
      errorResponse = this.newErrorResponse(
          this.newMeta(POST, 500, timers),
          this.newLinks(uriInfo), failure);
    }

    // check if this is a standard HTTP request
    if (eventBuilder == null && webSocketSession == null) {
      throw this.newInternalServerErrorException(
          POST, uriInfo, timers, failure);
    }

    if (eventBuilder != null) {
      // handle SSE response
      OutboundSseEvent abortEvent
          = eventBuilder.name(PROGRESS_EVENT)
          .id(String.valueOf(eventId++))
          .mediaType(APPLICATION_JSON_TYPE)
          .data(response)
          .reconnectDelay(RECONNECT_DELAY)
          .build();
      sseEventSink.send(abortEvent);

      OutboundSseEvent failEvent
          = eventBuilder.name(FAILED_EVENT)
          .id(String.valueOf(eventId++))
          .mediaType(APPLICATION_JSON_TYPE)
          .data(errorResponse)
          .reconnectDelay(RECONNECT_DELAY)
          .build();
      sseEventSink.send(failEvent);
      sseEventSink.close();
    }

    // check if we have a web socket session
    if (webSocketSession != null) {
      try {
        webSocketSession.getBasicRemote().sendObject(response);
        webSocketSession.getBasicRemote().sendObject(errorResponse);

      } catch (RuntimeException e) {
        e.printStackTrace();
        throw e;

      } catch (Exception e) {
        e.printStackTrace();
        throw new RuntimeException(e);
      }
    }

    // return null
    return null;
  }

  /**
   * Populates the specified {@link Map} with the data source mappings found
   * in the specified JSON text.
   *
   * @param dataSourceMap The {@link Map} to be populated.
   * @param mapDataSources The JSON text describing the data source mappings.
   * @param provider The {@link SzApiProvider} to use.
   * @param timers The {@link Timers} for the operation.
   * @param uriInfo The {@link UriInfo} for the operation.
   */
  default void processDataSources(Map<String, String> dataSourceMap,
                                  String              mapDataSources,
                                  SzApiProvider       provider,
                                  Timers              timers,
                                  UriInfo             uriInfo)
  {
    // check if the mapDataSources parameter is provided
    if (mapDataSources != null && mapDataSources.trim().length() > 0) {
      try {
        JsonObject jsonObject = JsonUtilities.parseJsonObject(mapDataSources);
        jsonObject.entrySet().forEach(entry -> {
          String key = entry.getKey();
          JsonValue value = entry.getValue();
          if (value.getValueType() != JsonValue.ValueType.STRING) {
            throw this.newBadRequestException(
                POST, uriInfo, timers,
                "At least one JSON property (\"" + key + "\") in the "
                    + "\"mapDataSources\" parameter does NOT have a "
                    + "String JSON value (" + JsonUtilities.toJsonText(value)
                    + "): " + mapDataSources);
          }
          String source = ((JsonString) value).getString().trim().toUpperCase();
          if (!provider.getDataSources(source).contains(source)) {
            throw newBadRequestException(
                POST, uriInfo, timers,
                "The data source mapping for \"" + key + "\" in the "
                    + "\"mapDataSources\" parameter has a value (\"" + source
                    + "\") that is not a configured data source: "
                    + mapDataSources);
          }
          dataSourceMap.put(key, source);
        });
      } catch (Exception e) {
        throw newBadRequestException(
            POST, uriInfo, timers,
            "The \"mapDataSources\" parameter is not a valid URL-encoded JSON "
                + "of String property names and String data source code values: "
                + mapDataSources);
      }
    }
  }

  /**
   * Populates the specified {@link Map} with the data source mappings found
   * in the specified {@link List} of encoded strings.
   *
   * @param dataSourceMap The {@link Map} to be populated.
   * @param mapDataSourceList The {@link List} of encoded strings describing the
   *                          data source mappings.
   * @param provider The {@link SzApiProvider} to use.
   * @param timers The {@link Timers} for the operation.
   * @param uriInfo The {@link UriInfo} for the operation.
   */
  default void processDataSources(Map<String, String> dataSourceMap,
                                  List<String>        mapDataSourceList,
                                  SzApiProvider       provider,
                                  Timers              timers,
                                  UriInfo             uriInfo)
  {
    // check if the mapDataSources parameter is provided
    if (mapDataSourceList != null && mapDataSourceList.size() > 0) {
      for (String mapping : mapDataSourceList) {
        char sep = mapping.charAt(0);
        int index = mapping.indexOf(sep, 1);
        if (index < 0 || index == mapping.length() - 1) {
          throw newBadRequestException(
              POST, uriInfo, timers,
              "The specified data source mapping is not a valid "
                  + "delimited string: " + mapping);
        }
        String source1 = mapping.substring(1, index).trim();
        String source2 = mapping.substring(index + 1).trim().toUpperCase();

        if (!provider.getDataSources(source2).contains(source2)) {
          throw newBadRequestException(
              POST, uriInfo, timers,
              "The data source mapping for \"" + source1 + "\" in the "
                  + "\"mapDataSource\" parameter has a value (\"" + source2
                  + "\") that is not a configured data source: "
                  + mapping);
        }
        dataSourceMap.put(source1, source2);
      }
    }
  }

  /**
   * Prepares for performing a bulk-loading operation by ensuring the server is
   * not in read-only mode and a long-running operation is authorized.
   *
   * @parma provider The {@link SzApiProvider} to use.
   * @param uriInfo The {@link UriInfo} for the request.
   * @param timers The {@link Timers} tracking timing for the operation.
   *
   * @return The {@link AccessToken} for the prolonged operation.
   *
   * @throws ForbiddenException If no load queue is configured.
   * @throws ServiceUnavailableException If too many long-running operaitons are
   *                                     already running.
   */
  default AccessToken prepareBulkLoadOperation(SzApiProvider  provider,
                                               UriInfo        uriInfo,
                                               Timers         timers)
      throws ForbiddenException, ServiceUnavailableException
  {
    this.ensureLoadingIsAllowed(provider, POST, uriInfo, timers);

    return this.prepareProlongedOperation(provider, POST, uriInfo, timers);
  }

  /**
   * Prepares for performing a bulk-loading operation by ensuring the
   * required data sources are configured.
   *
   * @parma provider The {@link SzApiProvider} to use.
   * @param uriInfo The {@link UriInfo} for the request.
   * @param timers The {@link Timers} tracking timing for the operation.
   * @param dataSource The data source to assign to the loaded records unless
   *                   another data source mapping supercedes this default.
   * @param mapDataSources The JSON string mapping specific data sources to
   *                       alternate data source names.  A mapping from
   *                       empty-string is used for mapping records with no
   *                       data source specified.
   * @param mapDataSourceList The {@link List} of delimited strings that begin
   *                          the delimiter, followed by the "from" data source
   *                          then the delimiter then the target data source.
   * @param dataSourceMap The {@link Map} of configured data source codes to
   *                      configured data sources.
   *
   * @throws BadRequestException If any of the data sources are not recognized.
   */
  default void prepareBulkDataMappings(SzApiProvider        provider,
                                       UriInfo              uriInfo,
                                       Timers               timers,
                                       String               dataSource,
                                       String               mapDataSources,
                                       List<String>         mapDataSourceList,
                                       Map<String, String>  dataSourceMap)
  {
    // normalize and validate the data source
    if (dataSource != null) {
      dataSource = dataSource.trim().toUpperCase();

      if (!provider.getDataSources(dataSource).contains(dataSource)) {
        throw this.newBadRequestException(
            POST, uriInfo, timers,
            "The value for the specified \"dataSource\" parameter is not a "
                + "configured data source: " + dataSource);
      }
    }

    this.processDataSources(
        dataSourceMap, mapDataSources, provider, timers, uriInfo);
    this.processDataSources(
        dataSourceMap, mapDataSourceList, provider, timers, uriInfo);

    // put the default overrides in the map with the null key
    if (dataSource != null) dataSourceMap.put(null, dataSource);
  }

  /**
   * Handles checking if the processing should be aborted and handles reporting
   * progress if the timing indicates that a progress update is due.
   *
   */
  default boolean checkAbortLoadDoProgress(
      UriInfo                   uriInfo,
      Timers                    timers,
      SzBulkLoadResult          bulkLoadResult,
      int                       maxFailures,
      ProgressState             progressState,
      Long                      progressPeriod,
      SseEventSink              sseEventSink,
      OutboundSseEvent.Builder  sseEventBuilder,
      Session                   webSocketSession)
  {
    // convert the progress period to nanoseconds
    Long progressNanos = (progressPeriod == null)
        ? null : progressPeriod * 1000000L;

    // count the number of failures
    int failedCount = bulkLoadResult.getFailedRecordCount()
        + bulkLoadResult.getIncompleteRecordCount();

    if (maxFailures > 0 && failedCount >= maxFailures) {
      bulkLoadResult.setStatus(ABORTED);
      return true;
    }

    long now = System.nanoTime();
    long duration = now - progressState.getStartTime();

    // check if the timing has gone beyond the specified progress period
    if ((progressNanos != null) && (duration > progressNanos)) {
      // create the update response if there is a client expecting it
      SzBulkLoadResponse update = null;
      if (sseEventBuilder != null || webSocketSession != null) {
        progressState.setStartTime(now);
        update = this.newBulkLoadResponse(
            POST, 200, uriInfo, timers, bulkLoadResult);
      }

      // check if sending an SSE response
      if (sseEventBuilder != null) {
        OutboundSseEvent event =
            sseEventBuilder.name(PROGRESS_EVENT)
                .id(String.valueOf(progressState.nextEventId()))
                .mediaType(APPLICATION_JSON_TYPE)
                .data(update)
                .reconnectDelay(RECONNECT_DELAY)
                .build();
        sseEventSink.send(event);
      }

      // check if sending a web socket response
      if (webSocketSession != null) {
        try {
          // send the web socket message and handle exceptions
          webSocketSession.getBasicRemote().sendObject(update);

        } catch (RuntimeException e) {
          e.printStackTrace();
          throw e;

        } catch (Exception e) {
          e.printStackTrace();
          throw new RuntimeException(e);
        }
      }
    }

    // return false since we are not aborting
    return false;
  }

  /**
   * The progress state to track when to produce progress updates for SSE and
   * web sockets.
   */
  class ProgressState {
    /**
     * The start time.
     */
    private long startTime = 0L;

    /**
     * The next event ID.
     */
    private int nextEventId = 0;

    /**
     * Default constructor.
     */
    public ProgressState() {
      this.startTime        = System.nanoTime();
      this.nextEventId      = 0;
    }

    /**
     * Gets the next event ID and increments the event ID for the next call.
     *
     * @return The next event ID.
     */
    public synchronized int nextEventId() {
      return this.nextEventId++;
    }

    /**
     * Gets the most recent start time.
     * @return The most recent start time.
     */
    public synchronized long getStartTime() {
      return this.startTime;
    }

    /**
     * Updates the start time to the specified time.
     * @param time The new start time.
     */
    public synchronized void setStartTime(long time) {
      this.startTime = time;
    }

  }

  /**
   * The progress updater thread to handle sending the progress updates.
   */
  class ProgressUpdater<T> extends Thread {
    /**
     * The time between progress updates in nanoseconds.
     */
    private long progressNanos = 0L;

    /**
     * The progress state.
     */
    private ProgressState progressState = null;

    /**
     * The {@link Object} to synchronize on.
     */
    protected final Object monitor;

    /**
     * The SSE event sink if sending updates via SSE.
     */
    private SseEventSink sseEventSink = null;

    /**
     * The SSE event builder if sending updates via SSE.
     */
    private OutboundSseEvent.Builder sseEventBuilder = null;

    /**
     * The Web Sockets Session if sending updates via web sockets.
     */
    private Session webSocketSession = null;

    /**
     * The supplier for providing the updates.
     */
    private Supplier<T> supplier = null;

    /**
     * Whether or not we are completed.
     */
    private boolean completed = false;

    /**
     * Constructs with the specified parameters.
     *
     * @param progressNanos The number of nano-seconds between progress updates.
     * @param progressState The {@link ProgressState} to manage the progress
     *                      updates.
     * @param monitor The object to synchronize, wait and notify on or
     *                <tt>null</tt> if it should synchronize on itself.
     * @param supplier THe {@link Supplier} for providing the update object.
     * @param sseEventSink The event sink for SSE if sending progress updates
     *                     via SSE, or <tt>null</tt> if not sending via SSE.
     * @param sseEventBuilder The SSE event builder if sending progress updates
     *                        via SSE, or <tt>null</tt> if not sending via SSE.
     * @param webSocketSession The web sockets {@link Session} if sending
     *                         progress udpates via web sockets, or
     *                         <tt>null</tt> if not sending via web sockets.
     */
    public ProgressUpdater(long                     progressNanos,
                           ProgressState            progressState,
                           Object                   monitor,
                           Supplier<T>              supplier,
                           SseEventSink             sseEventSink,
                           OutboundSseEvent.Builder sseEventBuilder,
                           Session                  webSocketSession)
    {
      Objects.requireNonNull(progressState,"The progressState cannot be null.");
      Objects.requireNonNull(supplier, "The supplier cannot be null.");

      this.progressNanos    = progressNanos;
      this.progressState    = progressState;
      this.monitor          = (monitor == null) ? this : monitor;
      this.supplier         = supplier;
      this.sseEventSink     = sseEventSink;
      this.sseEventBuilder  = sseEventBuilder;
      this.webSocketSession = webSocketSession;
    }

    /**
     * Marks this instance as completed.
     */
    public void complete() {
      synchronized (this.monitor) {
        this.completed = true;
        monitor.notifyAll();
      }
    }

    /**
     * Checks if this instance is completed.
     *
     * @return <tt>true</tt> if this instance is completed, otherwise
     *         <tt>false</tt>.
     */
    public boolean isCompleted() {
      synchronized (this.monitor) {
        return this.completed;
      }
    }

    /**
     * Implemented to send the progress updates periodically.
     */
    public void run() {
      while (!this.isCompleted()) {
        long now        = System.nanoTime();
        long duration   = now - this.progressState.getStartTime();
        long sleepTime  = (this.progressNanos - duration) / 1000000L;

        // check if it is not yet time for the next progress update
        if (sleepTime > 0) {
          // sleep for the
          synchronized (this.monitor) {
            try {
              // wait for notification or the maximum sleep time
              this.monitor.wait(sleepTime);
            } catch (InterruptedException ignore) {
              // do nothing -- ignore
            }
          }

        } else {
          // send a progress update (if not completed)
          this.sendProgressUpdate();
        }
      }
    }

    /**
     * Sends the next progress update.
     */
    protected void sendProgressUpdate() {
      synchronized (this.monitor) {
        // check if already completed
        if (this.isCompleted()) return;

        // get the current time
        long now = System.nanoTime();

        // create the update response if there is a client expecting it
        T update = null;
        if (this.sseEventBuilder != null || this.webSocketSession != null) {
          this.progressState.setStartTime(now);
          update = this.supplier.get();
        }

        // check if sending an SSE response
        if (this.sseEventBuilder != null) {
          OutboundSseEvent event =
              this.sseEventBuilder.name(PROGRESS_EVENT)
                  .id(String.valueOf(this.progressState.nextEventId()))
                  .mediaType(APPLICATION_JSON_TYPE)
                  .data(update)
                  .reconnectDelay(RECONNECT_DELAY)
                  .build();
          this.sseEventSink.send(event);
        }

        // check if sending a web socket response
        if (this.webSocketSession != null) {
          try {
            // send the web socket message and handle exceptions
            this.webSocketSession.getBasicRemote().sendObject(update);

          } catch (RuntimeException e) {
            e.printStackTrace();
            throw e;

          } catch (Exception e) {
            e.printStackTrace();
            throw new RuntimeException(e);
          }
        }
      }
    }
  }

}

public interface SzApiProvider {
  /**
   * Until we come up with a better method, use a simple factory to make
   * the global provider instance available.
   */
  class Factory {
    /**
     * The installed {@link SzApiProvider}.
     */
    private static SzApiProvider PROVIDER = null;

    /**
     * The {@link AccessToken} to authorizing uninstalling the provider.
     */
    private static AccessToken ACCESS_TOKEN = null;

    /**
     * Install a provider.  This fails if a provider is already installed.
     *
     * @param provider The non-null provider to install.
     *
     * @throws NullPointerException If the specified parameter is <tt>null</tt>.
     *
     * @throws IllegalStateException If a provider is already installed.
     */
    public static synchronized AccessToken installProvider(SzApiProvider provider) {
      if (provider == null) {
        throw new NullPointerException(
            "The specified provider cannot be null.");
      }
      if (PROVIDER != null) {
        throw new IllegalStateException(
            "An SzApiProvider is already installed: "
            + PROVIDER.getClass().getName());
      }
      PROVIDER = provider;
      ACCESS_TOKEN = new AccessToken();
      return ACCESS_TOKEN;
    }

    /**
     * Uninstalls the provider.  This does nothing if no provider is installed.
     *
     * @param token The {@link AccessToken} with which the provider was
     *              installed.
     *
     * @throws IllegalStateException If the specifid token is not the expected
     *                               token.
     */
    public static synchronized void uninstallProvider(AccessToken token)
      throws IllegalStateException
    {
      if (ACCESS_TOKEN != null && ACCESS_TOKEN != token) {
        throw new IllegalStateException(
            "The specified access token was not the expected access token.");
      }
      PROVIDER = null;
      ACCESS_TOKEN = null;
    }

    /**
     * Returns the installed {@link SzApiProvider}.  If no provider is installed
     * then an exception is thrown.
     *
     * @return The installed {@link SzApiProvider}.
     *
     * @throws IllegalStateException If no provider is installed.
     */
    public static synchronized SzApiProvider getProvider()
      throws IllegalStateException
    {
      if (PROVIDER == null) {
        IllegalStateException e = new IllegalStateException(
            "No SzApiProvider has been installed.");
        e.printStackTrace();
        throw e;
      }
      return PROVIDER;
    }
  }

  /**
   * Returns a description for the provider.  This is useful for inclusion
   * in the meta data for each response.
   *
   * @return A description for the provider.
   */
  String getDescription();

  /**
   * Returns the associated {@link G2Product} API implementation.
   *
   * @return The associated {@link G2Product} API implementation.
   */
  G2Product getProductApi();

  /**
   * Returns the associated {@link G2Engine} API implementation.
   *
   * @return The associated {@link G2Engine} API implementation.
   */
  G2Engine getEngineApi();

  /**
   * Returns the associated {@link G2Config} API implementation.
   *
   * @return The associated {@link G2Config} API implementation.
   */
  G2Config getConfigApi();

  /**
   * Returns the associated {@link G2ConfigMgr} API implementation.
   * This returns <tt>null</tt> if the configuration is not automatically
   * being picked up as the current default configuration.
   *
   * @return The associated {@link G2ConfigMgr} API implementation, or
   *         <tt>null</tt> if the configuration is not automatically
   *         being picked up as the current default configuration.
   */
  G2ConfigMgr getConfigMgrApi();

  /**
   * Returns the associated {@link G2Diagnostic} API implementation.
   *
   * @return The associated {@link G2Diagnostic} API implementation.
   */
  G2Diagnostic getDiagnosticApi();

  /**
   * Gets the version number of the REST API provider implementation.
   *
   * @return The version number of the REST API provider implementation.
   */
  String getApiProviderVersion();

  /**
   * Gets the version number of the REST API specification implemented by
   * this provider.
   *
   * @return The version number of the REST API specification implemented by
   *         this provider.
   */
  String getRestApiVersion();

  /**
   * Gets the version for the underlying runtime native Senzing API.
   *
   * @return The version for the underlying runtime native Senzing API.
   */
  String getNativeApiVersion();

  /**
   * Gets the build version for the underlying runtime native Senzing API.
   *
   * @return The build version for the underlying runtime native Senzing API.
   */
  String getNativeApiBuildVersion();

  /**
   * Gets the build number for the underlying runtime native Senzing API.
   *
   * @return The build number for the underlying runtime native Senzing API.
   */
  String getNativeApiBuildNumber();

  /**
   * Gets the build date for the underlying runtime native Senzing API.
   *
   * @return The build date for the underlying runtime native Senzing API.
   */
  Date getNativeApiBuildDate();

  /**
   * Gets the configuration compatibility version for the underlying runtime
   * native Senzing API.
   *
   * @return The configuration compatibility version for the underlying runtime
   *         native Senzing API.
   */
  String getConfigCompatibilityVersion();

  /**
   * Returns the concurrency for the API provider.  This is the number
   * of initialized threads to do work against the Senzing repository.
   * This method returns
   *
   * @return The maximum concurrency for the API provider, or zero (0) if
   *         the number of threads is unknown.
   */
  int getConcurrency();

  /**
   * Returns the base path for the REST API.  Typically this is <tt>"/"</tt>,
   * but it may be a sub-path.
   *
   * @return The base path for the REST API.
   */
  String getBasePath();

  /**
   * Gets the maximum number of bytes for both text and binary web sockets
   * messages.
   *
   * @return The maximum number of bytes for both text and binary web sockets
   *         messages.
   */
  int getWebSocketsMessageMaxSize();

  /**
   * Executes the specified task with the proper thread for utilizing the
   * various G2 API implementations.
   *
   * @param task The Task to execute.
   * @param <T> The return value for the task.
   * @param <E> The exception type that may be thrown by the task.
   * @return Returns an instance of type <tt>T</tt> as obtained from the
   *         specified task.
   * @throws E If the specified task fails with an exception.
   */
  <T, E extends Exception> T executeInThread(WorkerThreadPool.Task<T, E> task)
      throws E;

  /**
   * Called before beginning an operation that may require a prolonged amount of
   * time to complete.  If this returns <tt>null</tt> then the caller should
   * <b>not</b> continue with the operation.  If this returns an {@link
   * AccessToken} instance then the operation is authorized to continue and the
   * caller should call {@link #concludeProlongedOperation(AccessToken)} with
   * the result when the operation is complete.
   *
   * @return The {@link AccessToken} that authorizes the operation or
   *         <tt>null</tt> if the operation is not authorized.
   */
  AccessToken authorizeProlongedOperation();

  /**
   * Called when completing a prolonged operation that was previously
   * {@linkplain #authorizeProlongedOperation() authorized}.  The specified
   * {@link AccessToken} cannot be null.
   *
   * @param token The {@link AccessToken} from the previous {@linkplain
   *              #authorizeProlongedOperation() authorization}.
   *
   * @throws NullPointerException If the specified {@link AccessToken} is
   *                              <tt>null</tt>.
   * @throws IllegalArgumentException If the specified {@link AccessToken} is
   *                                  not recognized from a previous
   *                                  authorization.
   */
  void concludeProlongedOperation(AccessToken token);

  /**
   * Gets the <b>unmodifiable</b> {@Link Set} of Data Source codes that
   * are configured.
   *
   * @param expectedDataSources The zero or more data source codes that the
   *                            caller expects to exist.
   *
   * @return The <b>unmodifiable</b> {@Link Set} of Data Source codes that
   *         are configured.
   */
  Set<String> getDataSources(String... expectedDataSources);

  /**
   * Gets the attribute class associated with a feature type code.
   *
   * @param featureType The feature type code.
   *
   * @return The attribute class for the specified feature type, or
   *         <tt>null</tt> if the specified feature type code is <tt>null</tt>
   *         or not recognized.
   */
  String getAttributeClassForFeature(String featureType);

  /**
   * Checks if the API is running in read-only mode.
   *
   * @return <tt>true</tt> if only read-only endpoints should be allowed,
   *         otherwise <tt>false</tt>.
   */
  boolean isReadOnly();

  /**
   * Checks if the API is running with admin features enabled.
   *
   * @return <tt>true</tt> if admin features are enabled, otherwise
   *         <tt>false</tt>.
   */
  boolean isAdminEnabled();

  /**
   * Checks if there is an info message sink configured.
   *
   * @return <tt>true</tt> if an info message sink is configured, and
   *         <tt>false</tt> if none is configured.
   */
  boolean hasInfoSink();

  /**
   * Gets the {@link SzMessageSink} for sending info messages when records are
   * loaded, deleted or re-evaluated.  This returns <tt>null</tt> if an info
   * queue is not configured.
   *
   * @return The {@link SzMessageSink} for sending the info messages, or
   *         <tt>null</tt> if none is configured.
   */
  SzMessageSink acquireInfoSink();

  /**
   * Releases the specified {@link SzMessageSink} back to the provider when
   * done using it.
   *
   * @param sink The {@link SzMessageSink} to release.
   */
  void releaseInfoSink(SzMessageSink sink);
}

public interface ServicesSupport {
  /**
   * The standardized {@link Timers} key used for the overall timing.
   */
  String OVERALL_TIMING = "overall";

  /**
   * The standardized {@link Timers} key used for the raw-data processing stage.
   */
  String PROCESS_RAW_DATA_TIMING = "processRawData";

  /**
   * The standardized {@link Timers} key used for the native API stage.
   */
  String NATIVE_API_TIMING = "nativeAPI";

  /**
   * The standardized {@link Timers} key used for the enqueued stage.
   */
  String ENQUEUED_TIMING = "enqueued";

  /**
   * The standardized {@link Timers} key used for the locking stage.
   */
  String LOCK_TIMING = "locking";

  /**
   * The standardized {@link Timers} key used for sending an asynchronous
   * message on a queue.
   */
  String ASYNC_SEND_TIMING = "asyncSend";

  /**
   * The queue name for tracking time of the INFO queue.
   */
  String INFO_QUEUE_NAME = "INFO";

  /**
   * HTTP Response code for server error.
   */
  int SERVER_ERROR = 500;

  /**
   * HTTP Response code for service unavailable error.
   */
  int SERVICE_UNAVAILABLE = 503;

  /**
   * HTTP Response code for bad request.
   */
  int BAD_REQUEST = 400;

  /**
   * HTTP Response code for forbidden.
   */
  int FORBIDDEN = 403;

  /**
   * HTTP Response code for "not found".
   * \
   */
  int NOT_FOUND = 404;

  /**
   * HTTP Response code for "not allowed".
   */
  int NOT_ALLOWED = 405;

  /**
   * Error code when a data source code is not found.
   */
  int DATA_SOURCE_NOT_FOUND_CODE = 27;

  /**
   * Error code when a record ID is not found.
   */
  int RECORD_NOT_FOUND_CODE = 33;

  /**
   * Error code when the entity ID is not found.
   */
  int ENTITY_NOT_FOUND_CODE = 37;

  /**
   * Default flags for retrieving records.
   */
  long DEFAULT_RECORD_FLAGS
      = G2_ENTITY_INCLUDE_RECORD_FORMATTED_DATA
      | G2_ENTITY_INCLUDE_RECORD_MATCHING_INFO
      | G2_ENTITY_INCLUDE_RECORD_JSON_DATA
      | G2_ENTITY_INCLUDE_RECORD_SUMMARY;

  /**
   * The default progress period as the number of milliseconds between sending
   * progress responses to the client for SSE and Web Sockets.
   */
  Long DEFAULT_PROGRESS_PERIOD = 3000L;

  /**
   * Gets the {@link SzApiProvider} to use.  The default implementation returns
   * the result from {@link SzApiProvider.Factory#getProvider()}.
   *
   * @return The {@link SzApiProvider} to use.
   */
  default SzApiProvider getApiProvider() {
    return SzApiProvider.Factory.getProvider();
  }

  /**
   * Creates a new instance of {@link SzMeta}.
   *
   * @param httpMethod     The HTTP method with which to construct.
   * @param httpStatusCode The HTTP response code.
   * @param timers         The {@link Timers} instance that tracked timing.
   * @return The new instance of {@link SzMeta}.
   */
  default SzMeta newMeta(SzHttpMethod httpMethod,
                         int httpStatusCode,
                         Timers timers) {
    return SzMeta.FACTORY.create(httpMethod, httpStatusCode, timers);
  }

  /**
   * Creates a new instance of {@link SzLinks} with the specified {@link
   * HttpServletRequest}.
   *
   * @param request The {@link HttpServletRequest} to use for the links.
   * @return The new instance of {@link SzLinks}
   */
  default SzLinks newLinks(HttpServletRequest request) {
    return SzLinks.FACTORY.create(request);
  }

  /**
   * Creates a new instance of {@link SzLinks} with the specified self link.
   *
   * @param uriInfo The {@link UriInfo} containing the self link.
   * @return The new instance of {@link SzLinks}
   */
  default SzLinks newLinks(UriInfo uriInfo) {
    return SzLinks.FACTORY.create(uriInfo);
  }

  /**
   * Creates an {@link InternalServerErrorException} and builds a response
   * with an {@link SzErrorResponse} using the specified {@link UriInfo}
   * and the specified exception.
   *
   * @param httpMethod The HTTP method for the request.
   * @param uriInfo    The {@link UriInfo} from the request.
   * @param timers     The {@link Timers} object for the timings that were taken.
   * @param exception  The exception that caused the error.
   * @return The {@link InternalServerErrorException}
   */
  default InternalServerErrorException newInternalServerErrorException(
      SzHttpMethod httpMethod,
      UriInfo uriInfo,
      Timers timers,
      Exception exception) {
    Response.ResponseBuilder builder = Response.status(SERVER_ERROR);
    builder.entity(this.newErrorResponse(
        this.newMeta(httpMethod, SERVER_ERROR, timers),
        this.newLinks(uriInfo), exception));
    builder.type(APPLICATION_JSON);
    return new InternalServerErrorException(builder.build());
  }

  /**
   * Creates an {@link ServiceUnavailableException} and builds a response
   * with an {@link SzErrorResponse} using the specified {@link UriInfo}
   * and the specified exception.
   *
   * @param httpMethod The HTTP method for the request.
   * @param uriInfo    The {@link UriInfo} from the request.
   * @param timers     The {@link Timers} object for the timings that were taken.
   * @param message    The message describing the error.
   * @return The {@link ServiceUnavailableException}
   */
  default ServiceUnavailableException newServiceUnavailableErrorException(
      SzHttpMethod httpMethod,
      UriInfo uriInfo,
      Timers timers,
      String message) {
    Response.ResponseBuilder builder = Response.status(SERVICE_UNAVAILABLE);

    builder.entity(this.newErrorResponse(
        this.newMeta(httpMethod, SERVICE_UNAVAILABLE, timers),
        this.newLinks(uriInfo), message));
    builder.type(APPLICATION_JSON);
    return new ServiceUnavailableException(builder.build());
  }

  /**
   * Creates an {@link InternalServerErrorException} and builds a response
   * with an {@link SzErrorResponse} using the specified  {@link UriInfo}
   * and the specified {@link G2Fallible} to get the last exception from.
   *
   * @param httpMethod The HTTP method for the request.
   * @param uriInfo    The {@link UriInfo} from the request.
   * @param timers     The {@link Timers} object for the timings that were taken.
   * @param fallible   The {@link G2Fallible} to get the last exception from.
   * @return The {@link InternalServerErrorException}
   */
  default InternalServerErrorException newInternalServerErrorException(
      SzHttpMethod httpMethod,
      UriInfo uriInfo,
      Timers timers,
      G2Fallible fallible) {
    Response.ResponseBuilder builder = Response.status(SERVER_ERROR);
    SzErrorResponse errorResponse = this.newErrorResponse(
        this.newMeta(httpMethod, SERVER_ERROR, timers),
        this.newLinks(uriInfo), fallible);
    builder.entity(errorResponse);
    builder.type(APPLICATION_JSON);
    fallible.clearLastException();
    return new InternalServerErrorException(
        errorResponse.getErrors().toString(),
        builder.build());
  }

  /**
   * Creates an {@link NotFoundException} and builds a response
