   * native Senzing API.
   *
   * @param configCompatibilityVersion The configuration compatibility version
   *                                   for the underlying runtime native
   *                                   Senzing API.
   */
  void setConfigCompatibilityVersion(String configCompatibilityVersion);

  /**
   * A {@link ModelProvider} for instances of {@link SzVersionInfo}.
   */
  interface Provider extends ModelProvider<SzVersionInfo> {
    /**
     * Creates a new instance of {@link SzVersionInfo}.
     *
     * @return The new instance of {@link SzVersionInfo}
     */
    SzVersionInfo create();
  }

  /**
   * Provides a default {@link Provider} implementation for {@link
   * SzVersionInfo} that produces instances of {@link SzVersionInfoImpl}.
   */
  class DefaultProvider extends AbstractModelProvider<SzVersionInfo>
      implements Provider
  {
    /**
     * Default constructor.
     */
    public DefaultProvider() {
      super(SzVersionInfo.class, SzVersionInfoImpl.class);
    }

    @Override
    public SzVersionInfo create() {
      return new SzVersionInfoImpl();
    }
  }

  /**
   * Provides a {@link ModelFactory} implementation for {@link SzVersionInfo}.
   */
  class Factory extends ModelFactory<SzVersionInfo, Provider> {
    /**
     * Default constructor.  This is public and can only be called after the
     * singleton master instance is created as it inherits the same state from
     * the master instance.
     */
    public Factory() {
      super(SzVersionInfo.class);
    }

    /**
     * Constructs with the default provider.  This constructor is private and
     * is used for the master singleton instance.
     * @param defaultProvider The default provider.
     */
    private Factory(Provider defaultProvider) {
      super(defaultProvider);
    }

    /**
     * Creates a new instance of {@link SzVersionInfo}.
     * @return The new instance of {@link SzVersionInfo}.
     */
    public SzVersionInfo create()
    {
      return this.getProvider().create();
    }
  }

  /**
   * The {@link Factory} instance for this interface.
   */
  Factory FACTORY = new Factory(new DefaultProvider());

  /**
   * Parses a JSON array of the engine API JSON to create or populate a
   * {@link List} of {@link SzVersionInfo} instances.
   *
   * @param list The {@link List} to populate or <tt>null</tt> if a new
   *             {@link List} should be created.
   *
   * @param jsonArray The {@link JsonArray} of {@link JsonObject} instances
   *                  to parse from the engine API.
   *
   * @return An unmodifiable view of the specified (or newly created) {@link
   *         List} of {@link SzVersionInfo} instances.
   */
  static List<SzVersionInfo> parseVersionInfoList(
      List<SzVersionInfo>   list,
      JsonArray             jsonArray)
  {
    if (list == null) {
      list = new ArrayList<>(jsonArray.size());
    }
    for (JsonObject jsonObject : jsonArray.getValuesAs(JsonObject.class)) {
      list.add(parseVersionInfo(null, jsonObject));
    }
    return list;
  }

  /**
   * Parses the engine API JSON to create an instance of {@link SzVersionInfo}.
   *
   * @param info The {@link SzVersionInfo} object to initialize or <tt>null</tt>
   *             if a new one should be created.
   *
   * @param jsonObject The {@link JsonObject} to parse from the engine API.
   *
   * @return The specified (or newly created) {@link SzVersionInfo}
   */
  static SzVersionInfo parseVersionInfo(SzVersionInfo info,
                                        JsonObject    jsonObject)
  {
    if (info == null) info = SzVersionInfo.FACTORY.create();

    String nativeVersion = JsonUtilities.getString(jsonObject, "VERSION");
    String buildVersion  = JsonUtilities.getString(jsonObject, "BUILD_VERSION");
    String buildNumber   = JsonUtilities.getString(jsonObject, "BUILD_NUMBER");

    JsonObject compatVersion
        = JsonUtilities.getJsonObject(jsonObject, "COMPATIBILITY_VERSION");

    String configCompatVersion = JsonUtilities.getString(compatVersion,
                                                     "CONFIG_VERSION");

    Date buildDate = null;
    if (buildNumber != null && buildNumber.length() > 0
        && buildNumber.indexOf(DEVELOPMENT_VERSION_TOKEN) < 0)
    {
      LocalDateTime localDateTime = LocalDateTime.parse(buildNumber,
                                                        BUILD_NUMBER_FORMATTER);
      ZonedDateTime zonedDateTime = localDateTime.atZone(BUILD_ZONE);
      buildDate = Date.from(zonedDateTime.toInstant());

    } else {
      buildDate = new Date();
    }

    info.setConfigCompatibilityVersion(configCompatVersion);
    info.setNativeApiVersion(nativeVersion);
    info.setNativeApiBuildDate(buildDate);
    info.setNativeApiBuildVersion(buildVersion);
    info.setNativeApiBuildNumber(buildNumber);

    return info;
  }
}

public class SzMessage {
  /**
   * The {@link Map} of message properties.
   */
  private Map<String, String> properties = null;

  /**
   * The message body.
   */
  private String body = null;

  /**
   * Default constructor.
   */
  public SzMessage() {
    this(null);
  }

  /**
   * Constructs with the specified message body.
   */
  public SzMessage(String body) {
    this.body = body;
  }

  /**
   * Gets an <b>unmodifiable</b> {@link Map} of the properties associated with
   * the message.
   *
   * @return An <b>unmodifiable</b> {@link Map} of the properties associated
   *         with the message.
   */
  public Map<String, String> getProperties() {
    if (this.properties == null) return Collections.emptyMap();
    return Collections.unmodifiableMap(this.properties);
  }

  /**
   * Gets the property value associated with the specified property key.  This
   * returns <tt>null</tt> if no property is set for the specified key.
   *
   * @param key The key for the property.
   *
   * @return The property value associated with the key, or <tt>null</tt> if no
   *         property value is set for the specified key.
   */
  public String getProperty(String key) {
    if (this.properties == null) return null;
    return this.properties.get(key);
  }

  /**
   * Sets the property value associated with the specified property key.
   *
   * @param key The key for the property.
   *
   * @param value The value for the property.
   */
  public void setProperty(String key, String value) {
    if (this.properties == null) {
      this.properties = new LinkedHashMap<>();
    }
    this.properties.put(key, value);
  }

  /**
   * Returns the message body associated with this message.
   *
   * @return The message body associated with this message.
   */
  public String getBody() {
    return this.body;
  }

  /**
   * Sets the message body associated with this message.
   *
   * @param body The message body associated with this message.
   */
  public void setBody(String body) {
    this.body = body;
  }

  /**
   * Implemented to a return a hash code for this instance.
   *
   * @return A hash code for this instance.
   */
  public int hashCode() {
    return Objects.hash(this.properties, this.body);
  }

  /**
   * Implemented to return <tt>true</tt> if and only if the specified parameter
   * is a non-null reference to an object of the same class with equivalent
   * message properties and message body.
   *
   * @param obj The object to compare against for equality.
   *
   * @return <tt>true</tt> if the objects are equal, otherwise <tt>false</tt>.
   */
  public boolean equals(Object obj) {
    if (this == obj) return true;
    if (obj == null) return false;
    if (this.getClass() != obj.getClass()) return false;
    SzMessage msg = (SzMessage) obj;
    if (!Objects.equals(this.properties, msg.properties)) return false;
    if (!Objects.equals(this.body, msg.body)) return false;
    return true;
  }
  /**
   * Implemented to return a diagnostic {@link String} describing this message.
   *
   * @return A diagnostic {@link String} describing this message.
   */
  public String toString() {
    // if there are then format as JSON
    return ("properties=[ " + this.getProperties()
            + " ], body=[ " + this.getBody() + " ]");
  }
}

public abstract class AbstractModelProvider<T> implements ModelProvider<T> {
  /**
   * The interface class for the instances produced by this builder.
   */
  private Class<T> interfaceClass;

  /**
   * The runtime class produced by this instance.
   */
  private Class<? extends T> runtimeClass;

  /**
   * Constructs with the specified interface class.
   *
   * @param interfaceClass The interface class produced by the builder.
   *
   * @param runtimeClass The runtime class produced by the builder.
   */
  public AbstractModelProvider(Class<T>           interfaceClass,
                                  Class<? extends T> runtimeClass)
  {
    validateClasses(interfaceClass, runtimeClass);

    // set the interface and runtime classes
    this.interfaceClass = interfaceClass;
    this.runtimeClass   = runtimeClass;
  }

  /**
   * Validates the specified interface and runtime class.  The interface class
   * must be an interface.  The runtime class must implement the interface class
   * and be a concrete class and have a default constructor (whether public or
   * private) so the object can be deserialized from JSON.
   *
   * @param interfaceClass The interface class produced by the builder.
   *
   * @param runtimeClass The runtime class produced by the builder.
   */
  public static <T> void validateClasses(Class<T>           interfaceClass,
                                         Class<? extends T> runtimeClass)
  {
    try {
      Objects.requireNonNull(interfaceClass,
                             "The interface class cannot be null");
      Objects.requireNonNull(runtimeClass,
                             "The runtime class cannot be null");

      // ensure the interface class is an interface
      if (!interfaceClass.isInterface()) {
        throw new IllegalArgumentException(
            "The specified interface class must be an interface: "
                + interfaceClass);
      }

      // ensures the runtime class extends the interface class
      if (!interfaceClass.isAssignableFrom(runtimeClass)) {
        throw new IllegalArgumentException(
            "The runtime class must implement the interface class.  "
                + "runtimeClass=[ " + runtimeClass.getName()
                + " ], interfaceClass=[ " + interfaceClass.getName() + " ]");
      }

      // check the runtime class
      if (!runtimeClass.isAnnotationPresent(JsonDeserialize.class)) {
        throw new IllegalArgumentException(
            "The runtime class (" + runtimeClass + ") must be annotated with "
                + "@JsonDeserialize to override the @JsonDeserialize specified in "
                + "the interface class (" + interfaceClass + ")");
      }

    } catch (RuntimeException e) {
      e.printStackTrace();
      throw e;
    }
  }

  /**
   * Returns the interface class with which this instance was constructed.
   *
   * @return The interface class with which this instance was constructed.
   */
  @Override
  public Class<T> getInterfaceClass() {
    return this.interfaceClass;
  }

  /**
   * Returns the runtime class with which this instance was constructed.
   *
   * @return The runtime class with which this instance was constructed.
   */
  @Override
  public Class<? extends T> getRuntimeClass() {
    return this.runtimeClass;
  }
}

@SuppressWarnings("unchecked")
public abstract class ModelFactory<T, P extends ModelProvider<T>>
  extends JsonDeserializer<T>
{
  private static InvocationHandler DUMMY_HANDLER = new InvocationHandler() {
    @Override
    public Object invoke(Object proxy, Method method, Object[] args)
        throws Throwable
    {
      throw new UnsupportedOperationException();
    }
  };

  /**
   * The factory state which is kept on a per-class basis (i.e.: globally).
   */
  private static class FactoryState<T, P extends ModelProvider<T>> {
    /**
     * The interface class for the instances produced by this builder.
     */
    private Class<T> interfaceClass;

    /**
     * The current provider for this factory.
     */
    private P currentProvider;

    /**
     * The original default provider.
     */
    private P defaultProvider;
  }

  /**
   * The map of factory state instances (per class).
   */
  private static final
    Map<Class<? extends ModelFactory>, FactoryState> STATE_MAP
      = new LinkedHashMap<>();

  /**
   * The {@link FactoryState} for this instance.
   */
  private final FactoryState<T, P> state;

  /**
   * Constructs with the specified interface class.
   *
   * @param defaultProvider The default provider for this factory.
   */
  protected ModelFactory(P defaultProvider)
  {
    Objects.requireNonNull(defaultProvider,
                           "The default provider cannot be null");

    AbstractModelProvider.validateClasses(defaultProvider.getInterfaceClass(),
                                          defaultProvider.getRuntimeClass());

    // set the interface and runtime classes
    synchronized (STATE_MAP) {
      FactoryState<T,P> state = STATE_MAP.get(this.getClass());
      // check if this is the first/master instance
      if (state == null) {
        state = new FactoryState<T,P>();
        state.interfaceClass  = defaultProvider.getInterfaceClass();
        state.currentProvider = defaultProvider;
        state.defaultProvider = defaultProvider;
        STATE_MAP.put(this.getClass(), state);

      } else {
        // verify that nobody is trying to change the interface class
        if (defaultProvider.getInterfaceClass() != state.interfaceClass) {
          throw new IllegalStateException(
              "The master state already exists and the interface class of the "
              + "specified default provider does not match.  expected=[ "
              + state.interfaceClass + " ], specified=[ "
              + defaultProvider.getInterfaceClass() + " ]");
        }

        // verify the default provider
        if (defaultProvider.getRuntimeClass()
            != state.defaultProvider.getRuntimeClass())
        {
          throw new IllegalStateException(
              "The master state already exists and the runtime class for the "
              + "original default provider does not match the runtime class of "
              + "the specified default provider.  expected=[ "
                  + state.defaultProvider.getRuntimeClass() + " ], specified=[ "
                  + defaultProvider.getRuntimeClass() + " ]");
        }
      }
      this.state = state;
    }
  }

  /**
   * Default constructor which simply inherits an existing singleton
   * "master" state.
   */
  protected ModelFactory(Class<T> interfaceClass)
  {
    Objects.requireNonNull(
        interfaceClass, "The interface class cannot be null");
    // check if the master instance already created the shared state
    FactoryState<T,P> state = null;
    // synchronize
    synchronized (STATE_MAP) {
      // get the state instance
      state = STATE_MAP.get(this.getClass());

      // check if it does not exist
      if (state == null) {
        // try to force initialization of the host class (which should create
        // the master instance if it conforms to the model factory pattern)
        try {
          // create a dummy proxy instance to force initialization
          Class[] interfaces = { interfaceClass };
          Object proxy = Proxy.newProxyInstance(
              this.getClass().getClassLoader(), interfaces, DUMMY_HANDLER);

          // use the proxy instance to ensure it is not optimized out
          if (proxy == null) {
            throw new IllegalStateException(
                "Failed to create proxy instance for " + interfaceClass);
          }
        } catch (Exception e) {
          // ignore
        }
      }
    }

    // check if the state is null at this point (only should be if the
    // initialization had to be forced above)
    if (state == null) {
      synchronized (STATE_MAP) {
        state = STATE_MAP.get(this.getClass());
        // check if this is the first/master instance
        if (state == null) {
          throw new IllegalStateException(
              "The master state does not yet exist.  Cannot construct: "
                  + this.getClass().getName());
        }
      }
    }

    // validate the interface class matches
    if (interfaceClass != state.interfaceClass) {
      throw new IllegalStateException(
          "The specified interface class does not match that of the shared "
          + "state.  expected=[ " + state.interfaceClass + " ], specified=[ "
          + interfaceClass + " ]");
    }

    // set the state
    this.state = state;
  }

  /**
   * Gets the interface class provided.
   *
   * @return The interface class provided.
   */
  public final Class<T> getInterfaceClass() {
    return this.getProvider().getInterfaceClass();
  }

  /**
   * Gets the runtime class instantiated that implements the interface class.
   *
   * @return The runtime class instantiated that implements the runtime class.
   */
  public final Class<? extends T> getRuntimeClass() {
    return this.getProvider().getRuntimeClass();
  }

  /**
   * Returns the currently installed {@link ModelProvider} for this instance.
   *
   * @return The currently installed {@link ModelProvider} for this instance.
   */
  public final P getProvider() {
    synchronized (this.state) {
      return this.state.currentProvider;
    }
  }

  /**
   * Installs a new {@link ModelProvider} instance for this factory.
   *
   * @param provider The {@link ModelProvider} to install.
   *
   * @throws IllegalArgumentException If the specified {@link ModelProvider}
   *                                  does not have the correct interface class.
   */
  public final void installProvider(P provider) {
    Objects.requireNonNull(provider, "The provider cannot be null");
    AbstractModelProvider.validateClasses(provider.getInterfaceClass(),
                                          provider.getRuntimeClass());
    synchronized (this.state) {
      this.state.currentProvider = provider;
    }
  }

  /**
   * Method to determine the {@link JsonDeserializer} for the current
   * {@linkplain #getRuntimeClass() runtime class}.
   *
   * @param context The {@link DeserializationContext} to use for finding the
   *                deserializer.
   * @return The {@link JsonDeserializer} to use.
   *
   * @throws JsonMappingException If a JSON mapping falure occurs.
   */
  protected JsonDeserializer<Object> getRuntimeDeserializer(
      DeserializationContext context)
      throws JsonMappingException
  {
    Class runtimeClass = this.getRuntimeClass();
    JavaType runtimeType = context.constructType(runtimeClass);
    JsonDeserializer result = context.findRootValueDeserializer(runtimeType);

    // handle the case where the implementation does not override the JSON
    // deserializer and attempt to find the bean deserializer to use
    if (result.getClass() == this.getClass()) {
      throw new IllegalStateException(
          "Runtime implementation class MUST override the deserializer "
          + "specified in the interface class via @JsonDeserialize annotation "
          + "or by some other means: " + runtimeClass);
    }

    // return the deserializer
    return result;
  }

  /**
   * Overridden to delegate to the deserializer returned by {@link
   * #getRuntimeDeserializer(DeserializationContext)}.
   * <p>
   * {@inheritDoc}
   * </p>
   */
  @Override
  public T deserialize(JsonParser parser, DeserializationContext context)
      throws JsonProcessingException, IOException
  {
    JsonDeserializer<Object> rtDeserializer
        = this.getRuntimeDeserializer(context);
    return (T) rtDeserializer.deserialize(parser, context);
  }

  /**
   * Overridden to delegate to the deserializer returned by {@link
   * #getRuntimeDeserializer(DeserializationContext)}.
   * <p>
   * {@inheritDoc}
   * </p>
   */
  @Override
  public T deserialize(JsonParser             parser,
                       DeserializationContext context,
                       T                      intoValue)
      throws JsonProcessingException, IOException
  {
    JsonDeserializer<Object> rtDeserializer
        = this.getRuntimeDeserializer(context);
    return (T) rtDeserializer.deserialize(parser, context, intoValue);
  }

  /**
   * Overridden to delegate to the deserializer returned by {@link
   * #getRuntimeDeserializer(DeserializationContext)}.
   * <p>
   * {@inheritDoc}
   * </p>
   */
  @Override
  public T deserializeWithType(JsonParser             parser,
                               DeserializationContext context,
                               TypeDeserializer       typeDeserializer)
      throws JsonProcessingException, IOException
  {
    JsonDeserializer<Object> rtDeserializer
        = this.getRuntimeDeserializer(context);
    return (T) rtDeserializer.deserializeWithType(
        parser, context, typeDeserializer);
  }

  /**
   * Overridden to return a reference to this instance.
   * <p>
   * {@inheritDoc}
   * </p>
   */
  @Override
  public JsonDeserializer<T> unwrappingDeserializer(NameTransformer unwrapper)
  {
    return this;
  }

  /**
   * Overridden to return a reference to this instance.
   * <p>
   * {@inheritDoc}
   * </p>
   */
  @Override
  public JsonDeserializer<?> replaceDelegatee(JsonDeserializer<?> delegatee)
  {
    return this;
  }

  /**
   * Overridden to return the result from {@link #getInterfaceClass()}.
   * <p>
   * {@inheritDoc}
   * </p>
   */
  @Override
  public Class<?> handledType() {
    return this.getInterfaceClass();
  }

  /**
   * Overridden to return <tt>false</tt>.
   * <p>
   * {@inheritDoc}
   * </p>
   */
  @Override
  public boolean isCachable() {
    return false;
  }

  /**
   * Overridden to return a reference to this instance.
   * <p>
   * {@inheritDoc}
   * </p>
   */
  @Override
  public JsonDeserializer<?> getDelegatee() {
    return this;
  }

  /**
   * Overridden to determine the property names for the current runtime class
   * and return them.
   * <p>
   * {@inheritDoc}
   * </p>
   */
  @Override
  public Collection<Object> getKnownPropertyNames() {
    try {
      Class<? extends T> runtimeClass = this.getRuntimeClass();
      BeanInfo beanInfo = Introspector.getBeanInfo(runtimeClass);
      Set<Object> result = new LinkedHashSet<>();
      for (PropertyDescriptor propDesc : beanInfo.getPropertyDescriptors()) {
        result.add(propDesc.getName());
      }
      return result;

    } catch (IntrospectionException e) {
      e.printStackTrace();
      return Collections.emptySet();
    }
  }

  @Override
  public T getNullValue(DeserializationContext context)
      throws JsonMappingException
  {
    JsonDeserializer<Object> rtDeserializer
        = this.getRuntimeDeserializer(context);
    return (T) rtDeserializer.getNullValue(context);
  }
}

public interface ModelProvider<T> {
  /**
   * Gets the interface class provided.
