  /**
   * Parses the specified text as a {@link List} of homogeneous
   * {@link SzEntityIdentifier} instances represented as an {@link
   * SzEntityIdentifiers} instance.
   *
   * @param text The text to parse.
   * @return The parsed {@link SzEntityIdentifiers} instance.
   */
  default SzEntityIdentifiers parseEntityIdentifiers(String text) {
    return SzEntityIdentifiers.valueOf(text);
  }

  /**
   * Parses the specified text as a {@link Set} of {@link SzRecordId}
   * instances.
   *
   * @param text The text to parse.
   * @return The parsed {@link Set} of {@link SzRecordId} instances.
   */
  default Set<SzRecordId> parseRecordIdentifiers(String text) {
    try {
      SzEntityIdentifiers identifiers = SzEntityIdentifiers.valueOf(text);
      if (identifiers.isEmpty()) return new LinkedHashSet<>();
      if (!identifiers.isHomogeneous()) throw new IllegalArgumentException();

      List<SzEntityIdentifier> list = identifiers.getIdentifiers();
      SzEntityIdentifier first = list.get(0);

      // ensure we have record ID's
      if (!(first instanceof SzRecordId)) {
        throw new IllegalArgumentException();
      }
      Set<SzRecordId> result = new LinkedHashSet<>();

      // add to the set
      for (SzEntityIdentifier identifier : list) {
        result.add((SzRecordId) identifier);
      }

      // return the result
      return result;

    } catch (IllegalArgumentException e) {
      e.printStackTrace();
      throw new IllegalArgumentException(
          "Not an array of record identifiers: " + text);
    }
  }

  /**
   * Parses a list of entity data instances from a {@link JsonArray}
   * describing a JSON array in the Senzing native API format for entity
   * features and creates and populates a new {@link List} of
   * {@link SzEntityData} instances.
   *
   * @param jsonArray                The {@link JsonArray} describing the JSON in the
   *                                 Senzing native API format.
   * @param featureToAttrClassMapper Mapping function to map feature names to
   *                                 attribute classes.
   * @return The populated (or created) {@link List} of {@link
   * SzEntityData} instances.
   */
  default List<SzEntityData> parseEntityDataList(
      JsonArray jsonArray,
      Function<String, String> featureToAttrClassMapper) {
    return SzEntityData.parseEntityDataList(
        null, jsonArray, featureToAttrClassMapper);
  }

  /**
   * Prepares for performing a long-running operation is authorized.
   *
   * @param method  The {@link SzHttpMethod} for the request.
   * @param uriInfo The {@link UriInfo} for the request.
   * @param timers  The {@link Timers} tracking timing for the operation.
   * @return The {@link AccessToken} for the prolonged operation.
   * @throws ServiceUnavailableException If too many long-running operaitons are
   *                                     already running.
   * @parma provider The {@link SzApiProvider} to use.
   */
  default AccessToken prepareProlongedOperation(SzApiProvider provider,
                                                SzHttpMethod method,
                                                UriInfo uriInfo,
                                                Timers timers)
      throws ForbiddenException, ServiceUnavailableException {
    AccessToken accessToken = provider.authorizeProlongedOperation();
    if (accessToken == null) {
      throw this.newServiceUnavailableErrorException(
          method, uriInfo, timers,
          "Too many prolonged operations running.  Try again later.");
    }
    return accessToken;
  }

  /**
   * Normalizes the specified {@link String}.  If <tt>null</tt> then
   * <tt>null</tt> is returned.  Otherwise, the {@link String} is trimmed of
   * leading and trailing whitespace and if empty-string then <tt>null</tt>
   * is returned, otherwise the trimmed {@link String} is returned.
   *
   * @param text The {@link String} to be normalized.
   * @return The normalized {@link String}.
   */
  default String normalizeString(String text) {
    if (text == null) return null;
    if (text.trim().length() == 0) return null;
    return text.trim();
  }

  /**
   * Gets the entity ID for the entity identifier which may be a record ID.
   *
   * @param httpMethod The {@link SzHttpMethod} for the request.
   * @param uriInfo The {@link UriInfo} for the request.
   * @param timers The {@link Timers} for the operation.
   * @param engineApi The {@link G2Engine} instance to use.
   * @param identifier The {@link SzEntityIdentifier} to resolve.
   * @return The {@link Long} entity ID.
   */
  default Long resolveEntityId(SzHttpMethod       httpMethod,
                               UriInfo            uriInfo,
                               Timers             timers,
                               G2Engine           engineApi,
                               SzEntityIdentifier identifier)
  {
    return this.resolveEntityId(httpMethod,
                                uriInfo,
                                timers,
                                engineApi,
                                identifier,
                                false);
  }

  /**
   * Gets the entity ID for the entity identifier which may be a record ID.
   *
   * @param httpMethod The {@link SzHttpMethod} for the request.
   * @param uriInfo The {@link UriInfo} for the request.
   * @param timers The {@link Timers} for the operation.
   * @param engineApi The {@link G2Engine} instance to use.
   * @param identifier The {@link SzEntityIdentifier} to resolve.
   * @param throwNotFound <code>true</code> if a not-found exception should be
   *                      thrown and <code>false</code> if a bad-request
   *                      exception should be thrown if a data source code,
   *                      record ID, or entity ID is not found.
   * @return The {@link Long} entity ID.
   */
  default Long resolveEntityId(SzHttpMethod       httpMethod,
                               UriInfo            uriInfo,
                               Timers             timers,
                               G2Engine           engineApi,
                               SzEntityIdentifier identifier,
                               boolean            throwNotFound)
  {
    // get the entity IDs
    if (identifier instanceof SzEntityId) {
      return ((SzEntityId) identifier).getValue();

    } else {
      SzRecordId  recordIdent = (SzRecordId) identifier;
      String      dataSource  = recordIdent.getDataSourceCode();
      String      recordId    = recordIdent.getRecordId();

      StringBuffer sb = new StringBuffer();
      this.callingNativeAPI(timers, "engine", "getEntityByRecordID");
      int result = engineApi.getEntityByRecordID(dataSource, recordId, 0, sb);
      this.calledNativeAPI(timers, "engine", "getEntityByRecordID");

      if (result != 0) {
        if (throwNotFound) {
          throw this.newPossiblyNotFoundException(
              httpMethod, uriInfo, timers, engineApi);
        } else {
          throw this.newPossiblyBadRequestException(
              httpMethod, uriInfo, timers, engineApi);
        }
      }

      // parse as a JSON object
      JsonObject jsonObject = JsonUtilities.parseJsonObject(sb.toString());
      jsonObject = jsonObject.getJsonObject("RESOLVED_ENTITY");

      // get the entity ID
      return JsonUtilities.getLong(jsonObject, "ENTITY_ID");
    }
  }

}

public class ServicesUtil {
  /**
   * The suppression state for info errors.
   */
  private static final ErrorLogSuppressor INFO_ERROR_SUPPRESSOR
      = new ErrorLogSuppressor();

  /**
   * The hash of the system identity codes of the last info message exception
   * as well as the the message object that was sent.
   */
  private static final ThreadLocal<Long> LAST_INFO_ERROR_HASH
      = new ThreadLocal<>();

  /**
   * Generates a 64-bit hash from the system identity hash codes of the two
   * specified objects.
   *
   * @param obj1 The first object whose identity hash code goes to the high-order
   *             bits.
   * @param obj2 The second object whose identity hash code goes to the low-order
   *             bits.
   *
   * @return The <tt>long</tt> hash code of the object pair.
   */
  public static long identityPairHash(Object obj1, Object obj2) {
    long high = (long) ((obj1 == null) ? 0 : System.identityHashCode(obj1));
    long low = (long) ((obj2 == null) ? 0 : System.identityHashCode(obj2));
    return (high << 32) | low;
  }

  /**
   * Logs an error related to sending asynchronous info messages.
   *
   * @param e The {@link Exception} that occurred.
   * @param message The info message that failed.
   */
  public static void logFailedAsyncInfo(Exception e, SzMessage message) {
    // check what was previously logged and avoid double-logging
    Long previous = LAST_INFO_ERROR_HASH.get();
    long hash = identityPairHash(e, message);
    if (previous != null && previous == hash) return;
    LAST_INFO_ERROR_HASH.set(hash);

    Date timestamp = new Date();
    String info = message.getBody();
    System.err.println(
        timestamp + ": FAILED TO SEND ASYNC INFO MESSAGE: " + info);
    synchronized (INFO_ERROR_SUPPRESSOR) {
      boolean suppressing = INFO_ERROR_SUPPRESSOR.isSuppressing();
      ErrorLogSuppressor.Result result = INFO_ERROR_SUPPRESSOR.updateOnError();
      switch (result.getState()) {
        case SUPPRESSED:
          if (!suppressing) {
            System.err.println(
                timestamp + ": SUPPRESSING ASYNC INFO MESSAGE ERRORS FOR "
                    + INFO_ERROR_SUPPRESSOR.getSuppressDuration() + "ms");
          }
          break;
        case REACTIVATED:
          if (result.getSuppressedCount() > 0) {
            System.err.println(
                timestamp + ": RESUMING ASYNC INFO MESSAGE ERRORS ("
                    + result.getSuppressedCount() + " SUPPRESSED)");
          }
        case ACTIVE:
          e.printStackTrace();
          break;
      }
    }
  }

  /**
   * Returns the Base {@link URI} given the specified request {@link URI}.
   *
   * @param requestUri The request {@link URI} for the request.
   *
   * @return The Base {@link URI} for the specified request {@link URI}.
   */
  public static URI getBaseUri(URI requestUri) {
    // determine the scheme
    String scheme = requestUri.getScheme();
    if (scheme.equalsIgnoreCase("wss")) {
      scheme = "https";
    } else if (scheme.equalsIgnoreCase("ws")) {
      scheme = "http";
    }

    // get the host
    String host = requestUri.getHost();

    // get the port
    int port = requestUri.getPort();
    String portText = ":" + port;
    if ((port == 80 && scheme.equalsIgnoreCase("http"))
        || (port == 443 && scheme.equalsIgnoreCase("https")))
    {
      portText = "";
    }

    // get the context path
    SzApiProvider provider = SzApiProvider.Factory.getProvider();
    String contextPath = provider.getBasePath();
    if (!contextPath.endsWith("/")) contextPath += "/";
    if (!contextPath.startsWith("/")) contextPath = "/" + contextPath;

    // build the URI
    String uriText = scheme + "://" + host + portText + contextPath;

    try {
      // return the result
      return new URI(uriText);
    } catch (URISyntaxException e) {
      throw new RuntimeException(e);
    }
  }

  /**
   * Returns the Base {@link URI} for the specified {@link HttpServletRequest}.
   *
   * @param request The {@link HttpServletRequest}.
   *
   * @return The Base {@link URI} for the specified {@link HttpServletRequest}.
   */
  public static URI getBaseUri(HttpServletRequest request) {
    // determine the scheme
    String scheme = request.getScheme();
    if (scheme.equalsIgnoreCase("wss")) {
      scheme = "https";
    } else if (scheme.equalsIgnoreCase("ws")) {
      scheme = "http";
    }

    // get the host
    String host = request.getServerName();

    // get the port
    int port = request.getServerPort();
    String portText = ":" + port;
    if ((port == 80 && scheme.equalsIgnoreCase("http"))
        || (port == 443 && scheme.equalsIgnoreCase("https")))
    {
      portText = "";
    }

    // get the context path
    String contextPath = request.getContextPath();
    if (!contextPath.endsWith("/")) contextPath += "/";
    if (!contextPath.startsWith("/")) contextPath = "/" + contextPath;

    // build the URI
    String uriText = scheme + "://" + host + portText + contextPath;

    try {
      // return the result
      return new URI(uriText);
    } catch (URISyntaxException e) {
      throw new RuntimeException(e);
    }
  }

}

public interface SzApiProvider {
  /**
   * Until we come up with a better method, use a simple factory to make
   * the global provider instance available.
   */
  class Factory {
    /**
     * The installed {@link SzApiProvider}.
     */
    private static SzApiProvider PROVIDER = null;

    /**
     * The {@link AccessToken} to authorizing uninstalling the provider.
     */
    private static AccessToken ACCESS_TOKEN = null;

    /**
     * Install a provider.  This fails if a provider is already installed.
     *
     * @param provider The non-null provider to install.
     *
     * @throws NullPointerException If the specified parameter is <tt>null</tt>.
     *
     * @throws IllegalStateException If a provider is already installed.
     */
    public static synchronized AccessToken installProvider(SzApiProvider provider) {
      if (provider == null) {
        throw new NullPointerException(
            "The specified provider cannot be null.");
      }
      if (PROVIDER != null) {
        throw new IllegalStateException(
            "An SzApiProvider is already installed: "
            + PROVIDER.getClass().getName());
      }
      PROVIDER = provider;
      ACCESS_TOKEN = new AccessToken();
      return ACCESS_TOKEN;
    }

    /**
     * Uninstalls the provider.  This does nothing if no provider is installed.
     *
     * @param token The {@link AccessToken} with which the provider was
     *              installed.
     *
     * @throws IllegalStateException If the specifid token is not the expected
     *                               token.
     */
    public static synchronized void uninstallProvider(AccessToken token)
      throws IllegalStateException
    {
      if (ACCESS_TOKEN != null && ACCESS_TOKEN != token) {
        throw new IllegalStateException(
            "The specified access token was not the expected access token.");
      }
      PROVIDER = null;
      ACCESS_TOKEN = null;
    }

    /**
     * Returns the installed {@link SzApiProvider}.  If no provider is installed
     * then an exception is thrown.
     *
     * @return The installed {@link SzApiProvider}.
     *
     * @throws IllegalStateException If no provider is installed.
     */
    public static synchronized SzApiProvider getProvider()
      throws IllegalStateException
    {
      if (PROVIDER == null) {
        IllegalStateException e = new IllegalStateException(
            "No SzApiProvider has been installed.");
        e.printStackTrace();
        throw e;
      }
      return PROVIDER;
    }
  }

  /**
   * Returns a description for the provider.  This is useful for inclusion
   * in the meta data for each response.
   *
   * @return A description for the provider.
   */
  String getDescription();

  /**
   * Returns the associated {@link G2Product} API implementation.
   *
   * @return The associated {@link G2Product} API implementation.
   */
  G2Product getProductApi();

  /**
   * Returns the associated {@link G2Engine} API implementation.
   *
   * @return The associated {@link G2Engine} API implementation.
   */
  G2Engine getEngineApi();

  /**
   * Returns the associated {@link G2Config} API implementation.
   *
   * @return The associated {@link G2Config} API implementation.
   */
  G2Config getConfigApi();

  /**
   * Returns the associated {@link G2ConfigMgr} API implementation.
   * This returns <tt>null</tt> if the configuration is not automatically
   * being picked up as the current default configuration.
   *
   * @return The associated {@link G2ConfigMgr} API implementation, or
   *         <tt>null</tt> if the configuration is not automatically
   *         being picked up as the current default configuration.
   */
  G2ConfigMgr getConfigMgrApi();

  /**
   * Returns the associated {@link G2Diagnostic} API implementation.
   *
   * @return The associated {@link G2Diagnostic} API implementation.
   */
  G2Diagnostic getDiagnosticApi();

  /**
   * Gets the version number of the REST API provider implementation.
   *
   * @return The version number of the REST API provider implementation.
   */
  String getApiProviderVersion();

  /**
   * Gets the version number of the REST API specification implemented by
   * this provider.
   *
   * @return The version number of the REST API specification implemented by
   *         this provider.
   */
  String getRestApiVersion();

  /**
   * Gets the version for the underlying runtime native Senzing API.
   *
   * @return The version for the underlying runtime native Senzing API.
   */
  String getNativeApiVersion();

  /**
   * Gets the build version for the underlying runtime native Senzing API.
   *
   * @return The build version for the underlying runtime native Senzing API.
   */
  String getNativeApiBuildVersion();

  /**
   * Gets the build number for the underlying runtime native Senzing API.
   *
   * @return The build number for the underlying runtime native Senzing API.
   */
  String getNativeApiBuildNumber();

  /**
   * Gets the build date for the underlying runtime native Senzing API.
   *
   * @return The build date for the underlying runtime native Senzing API.
   */
  Date getNativeApiBuildDate();

  /**
   * Gets the configuration compatibility version for the underlying runtime
   * native Senzing API.
   *
   * @return The configuration compatibility version for the underlying runtime
   *         native Senzing API.
   */
  String getConfigCompatibilityVersion();

  /**
   * Returns the concurrency for the API provider.  This is the number
   * of initialized threads to do work against the Senzing repository.
   * This method returns
   *
   * @return The maximum concurrency for the API provider, or zero (0) if
   *         the number of threads is unknown.
   */
  int getConcurrency();

  /**
   * Returns the base path for the REST API.  Typically this is <tt>"/"</tt>,
   * but it may be a sub-path.
   *
   * @return The base path for the REST API.
   */
  String getBasePath();

  /**
   * Gets the maximum number of bytes for both text and binary web sockets
   * messages.
   *
   * @return The maximum number of bytes for both text and binary web sockets
   *         messages.
   */
  int getWebSocketsMessageMaxSize();

  /**
   * Executes the specified task with the proper thread for utilizing the
   * various G2 API implementations.
   *
   * @param task The Task to execute.
   * @param <T> The return value for the task.
   * @param <E> The exception type that may be thrown by the task.
   * @return Returns an instance of type <tt>T</tt> as obtained from the
   *         specified task.
   * @throws E If the specified task fails with an exception.
   */
  <T, E extends Exception> T executeInThread(WorkerThreadPool.Task<T, E> task)
      throws E;

  /**
   * Called before beginning an operation that may require a prolonged amount of
   * time to complete.  If this returns <tt>null</tt> then the caller should
   * <b>not</b> continue with the operation.  If this returns an {@link
   * AccessToken} instance then the operation is authorized to continue and the
   * caller should call {@link #concludeProlongedOperation(AccessToken)} with
   * the result when the operation is complete.
   *
   * @return The {@link AccessToken} that authorizes the operation or
   *         <tt>null</tt> if the operation is not authorized.
   */
  AccessToken authorizeProlongedOperation();

  /**
   * Called when completing a prolonged operation that was previously
   * {@linkplain #authorizeProlongedOperation() authorized}.  The specified
   * {@link AccessToken} cannot be null.
   *
   * @param token The {@link AccessToken} from the previous {@linkplain
   *              #authorizeProlongedOperation() authorization}.
   *
   * @throws NullPointerException If the specified {@link AccessToken} is
   *                              <tt>null</tt>.
   * @throws IllegalArgumentException If the specified {@link AccessToken} is
   *                                  not recognized from a previous
   *                                  authorization.
   */
  void concludeProlongedOperation(AccessToken token);

  /**
   * Gets the <b>unmodifiable</b> {@Link Set} of Data Source codes that
   * are configured.
   *
   * @param expectedDataSources The zero or more data source codes that the
   *                            caller expects to exist.
   *
   * @return The <b>unmodifiable</b> {@Link Set} of Data Source codes that
   *         are configured.
   */
  Set<String> getDataSources(String... expectedDataSources);

  /**
   * Gets the attribute class associated with a feature type code.
   *
   * @param featureType The feature type code.
   *
   * @return The attribute class for the specified feature type, or
   *         <tt>null</tt> if the specified feature type code is <tt>null</tt>
   *         or not recognized.
   */
  String getAttributeClassForFeature(String featureType);

  /**
   * Checks if the API is running in read-only mode.
   *
   * @return <tt>true</tt> if only read-only endpoints should be allowed,
   *         otherwise <tt>false</tt>.
   */
  boolean isReadOnly();

  /**
   * Checks if the API is running with admin features enabled.
   *
   * @return <tt>true</tt> if admin features are enabled, otherwise
   *         <tt>false</tt>.
   */
  boolean isAdminEnabled();

  /**
   * Checks if there is an info message sink configured.
   *
   * @return <tt>true</tt> if an info message sink is configured, and
   *         <tt>false</tt> if none is configured.
   */
  boolean hasInfoSink();

  /**
   * Gets the {@link SzMessageSink} for sending info messages when records are
   * loaded, deleted or re-evaluated.  This returns <tt>null</tt> if an info
   * queue is not configured.
   *
   * @return The {@link SzMessageSink} for sending the info messages, or
   *         <tt>null</tt> if none is configured.
   */
  SzMessageSink acquireInfoSink();

  /**
   * Releases the specified {@link SzMessageSink} back to the provider when
   * done using it.
   *
   * @param sink The {@link SzMessageSink} to release.
   */
  void releaseInfoSink(SzMessageSink sink);
}

public class SzMessage {
  /**
   * The {@link Map} of message properties.
   */
  private Map<String, String> properties = null;

  /**
   * The message body.
   */
  private String body = null;

  /**
   * Default constructor.
   */
  public SzMessage() {
    this(null);
  }

  /**
   * Constructs with the specified message body.
   */
  public SzMessage(String body) {
    this.body = body;
  }

  /**
   * Gets an <b>unmodifiable</b> {@link Map} of the properties associated with
   * the message.
   *
   * @return An <b>unmodifiable</b> {@link Map} of the properties associated
   *         with the message.
   */
  public Map<String, String> getProperties() {
    if (this.properties == null) return Collections.emptyMap();
    return Collections.unmodifiableMap(this.properties);
  }

  /**
   * Gets the property value associated with the specified property key.  This
   * returns <tt>null</tt> if no property is set for the specified key.
   *
   * @param key The key for the property.
   *
   * @return The property value associated with the key, or <tt>null</tt> if no
   *         property value is set for the specified key.
   */
  public String getProperty(String key) {
    if (this.properties == null) return null;
    return this.properties.get(key);
  }

  /**
   * Sets the property value associated with the specified property key.
   *
   * @param key The key for the property.
   *
   * @param value The value for the property.
   */
  public void setProperty(String key, String value) {
    if (this.properties == null) {
      this.properties = new LinkedHashMap<>();
    }
    this.properties.put(key, value);
  }

  /**
   * Returns the message body associated with this message.
   *
   * @return The message body associated with this message.
   */
  public String getBody() {
    return this.body;
  }

  /**
   * Sets the message body associated with this message.
   *
   * @param body The message body associated with this message.
   */
  public void setBody(String body) {
    this.body = body;
  }

  /**
   * Implemented to a return a hash code for this instance.
   *
   * @return A hash code for this instance.
   */
  public int hashCode() {
    return Objects.hash(this.properties, this.body);
  }

  /**
   * Implemented to return <tt>true</tt> if and only if the specified parameter
   * is a non-null reference to an object of the same class with equivalent
   * message properties and message body.
   *
   * @param obj The object to compare against for equality.
   *
   * @return <tt>true</tt> if the objects are equal, otherwise <tt>false</tt>.
   */
  public boolean equals(Object obj) {
    if (this == obj) return true;
    if (obj == null) return false;
    if (this.getClass() != obj.getClass()) return false;
    SzMessage msg = (SzMessage) obj;
    if (!Objects.equals(this.properties, msg.properties)) return false;
    if (!Objects.equals(this.body, msg.body)) return false;
    return true;
  }
  /**
   * Implemented to return a diagnostic {@link String} describing this message.
   *
   * @return A diagnostic {@link String} describing this message.
   */
  public String toString() {
    // if there are then format as JSON
    return ("properties=[ " + this.getProperties()
            + " ], body=[ " + this.getBody() + " ]");
  }
}

