  /**
   * Implements the <tt>GET /entity-paths</tt> operation.
   *
   * @param fromParam The {@link SzEntityIdentifier} for the start of the
   *                  requested path.
   * @param toParam The {@link SzEntityIdentifier} for the end of the requested
