   * @return <tt>true</tt> if they are consistent, and <tt>false</tt> if not.
   */
  protected boolean checkConsistent(Set<SzEntityIdentifier> entities) {
    if (entities != null && !entities.isEmpty()) {
      Class idClass = null;
      for (SzEntityIdentifier id : entities) {
        if (idClass == null) {
